manifest.css:
/* Isaac Basement for DSH
 * Work UI only. Settings, Agent presets, plugin/model management,
 * Cordis/Aion panels, dialogs, menus and global tokens stay untouched.
 */

@font-face {
  font-family: "Fusion Pixel Isaac";
  src: url("data:font/woff2;base64,") format("woff2");
  font-display: swap;
}

/* Shared work-area palette. These variables are scoped to app work surfaces. */
.hHd-Xa_root,
.wSkVaW_root {
  --isaac-ink: #e7e4df;
  --isaac-muted: #aaa39b;
  --isaac-dim: #77716b;
  --isaac-blood: #873125;
  --isaac-blood-bright: #b94b38;
  --isaac-gold: #c69a59;
  --isaac-line: rgba(132, 82, 57, .48);
  --isaac-panel: #171618;
  --isaac-panel-soft: #201d1c;
}

/* ---------------- Ambient room stage ----------------
 * Mature DSH skins own a backdrop and then place readable panes over it.
 * The room is therefore a stage, never the text canvas itself. */
body[data-dsh-isaac] {
  --isaac-burning-room-image: url("data:image/png;base64,");
  color: var(--isaac-ink, #e7e4df);
  background: #0c0705;
}

.isaacStage {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  background-color: #130a07;
  background-image:
    radial-gradient(ellipse at center, rgba(21, 13, 10, .12) 0%, rgba(10, 6, 5, .58) 68%, #080504 100%),
    var(--isaac-burning-room-image);
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  image-rendering: pixelated;
  filter: saturate(.86) contrast(1.06);
}

.isaacStage::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(0, 0, 0, .38), transparent 24%, transparent 76%, rgba(0, 0, 0, .38)),
    linear-gradient(180deg, rgba(0, 0, 0, .18), transparent 24%, transparent 72%, rgba(0, 0, 0, .42));
}

.isaacStage::after {
  content: "";
  position: absolute;
  inset: -4%;
  background:
    radial-gradient(circle at 12% 48%, rgba(255, 104, 34, .3), transparent 10%),
    radial-gradient(circle at 88% 48%, rgba(255, 104, 34, .26), transparent 10%);
  opacity: .42;
  animation: isaacFirelight 3.2s ease-in-out infinite alternate;
}

.isaacTorch {
  position: fixed;
  top: 46%;
  z-index: 0;
  width: 14px;
  height: 28px;
  opacity: .25;
  border-radius: 55% 45% 60% 40%;
  background: radial-gradient(circle at 50% 72%, #fff2a6 0 16%, #f59a34 18% 46%, #a62f1f 48% 68%, transparent 70%);
  filter: drop-shadow(0 0 14px rgba(244, 91, 28, .8));
  animation: isaacTorch 1.2s steps(3, end) infinite alternate;
  pointer-events: none;
}
.isaacTorchLeft { left: 8.5%; }
.isaacTorchRight { right: 8.5%; animation-delay: -.55s; }
body[data-dsh-isaac]:has(.wSkVaW_root[data-phase="hero"]) .isaacTorch { opacity: .9; }

.isaacDoor {
  position: fixed;
  left: calc(50% + 140px);
  z-index: 1;
  pointer-events: none;
  opacity: 0;
  transition: opacity 220ms ease;
}
.isaacDoor {
  top: -15px;
  width: 142px;
  height: 82px;
  transform: translateX(-50%);
  border: 11px solid #1b0d09;
  border-bottom-width: 14px;
  border-radius: 0 0 46px 46px;
  background:
    radial-gradient(ellipse at 50% 112%, #180906 0 38%, transparent 40%),
    repeating-linear-gradient(90deg, #49271d 0 18px, #342018 18px 21px);
  box-shadow: inset 0 -8px rgba(0, 0, 0, .42), 0 8px 0 #6d3b2b, 0 14px 24px rgba(0, 0, 0, .5);
}
.isaacDoor::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -8px;
  width: 40px;
  height: 8px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: #8c241b;
  box-shadow: 0 5px 0 -2px #6a170f;
}
body[data-dsh-isaac]:has(.wSkVaW_root[data-phase="hero"]) .isaacDoor { opacity: .88; }

@keyframes isaacFirelight {
  from { transform: scale(1); opacity: .34; }
  to { transform: scale(1.025); opacity: .56; }
}
@keyframes isaacTorch {
  from { transform: translateY(1px) rotate(-3deg) scale(.94, 1.03); }
  to { transform: translateY(-2px) rotate(4deg) scale(1.08, .92); }
}

@media (prefers-reduced-motion: reduce) {
  .isaacStage::after,
  .isaacTorch { animation: none; }
}

body[data-dsh-isaac] [id="root"] {
  position: relative;
  z-index: 1;
  background: transparent;
}
body[data-dsh-isaac] [data-slot="root"] > div:has([data-slot="conversation"]) {
  background: transparent;
}
body[data-dsh-isaac] [data-slot="root"] > div > div:has(> [data-slot="sidebar"]) {
  background: rgba(18, 12, 10, .84);
  border-right: 2px solid #24130d;
  box-shadow: inset -1px 0 rgba(170, 88, 48, .24), 8px 0 30px rgba(0, 0, 0, .28);
}
body[data-dsh-isaac] [data-slot="root"] > div > div:has(> [data-slot="conversation"]) {
  background: rgba(13, 13, 15, .925);
  box-shadow: inset 0 0 0 1px rgba(139, 78, 49, .16);
}
body[data-dsh-isaac]:has(.wSkVaW_root[data-phase="hero"]) [data-slot="root"] > div > div:has(> [data-slot="conversation"]) {
  background: rgba(12, 8, 7, .28);
}
body[data-dsh-isaac] .wSkVaW_root[data-phase="hero"] {
  background: transparent;
}

/* ---------------- Sidebar: basement material kept behind the navigation ---------------- */
.hHd-Xa_root {
  color: var(--isaac-ink);
  background-color: #181615;
  background-image:
    linear-gradient(rgba(24, 17, 14, .76), rgba(16, 11, 9, .86)),
    url("data:image/png;base64,");
  background-repeat: repeat;
  background-size: auto, 64px 64px;
  box-shadow: inset -1px 0 #090504, inset -3px 0 rgba(156, 74, 41, .34);
}

.hHd-Xa_logoRow {
  color: #e6e1da;
  background: rgba(13, 13, 14, .74);
  border-bottom: 1px solid rgba(122, 76, 52, .26);
}

.hHd-Xa_newSession {
  position: relative;
  font-family: "Fusion Pixel Isaac", system-ui, sans-serif;
  letter-spacing: .04em;
  color: #eee9e2;
  background:
    repeating-linear-gradient(0deg, rgba(43, 20, 12, .16) 0 2px, transparent 2px 5px),
    linear-gradient(180deg, #6c4938, #493126 58%, #35241d);
  border: 2px solid #1b0f0a;
  outline: 1px solid #8e6047;
  outline-offset: -3px;
  box-shadow: inset 0 2px rgba(255, 225, 194, .13), inset 0 -3px rgba(0, 0, 0, .32), 0 3px 8px rgba(0, 0, 0, .34);
}
.hHd-Xa_newSession:hover {
  color: #fff6e9;
  filter: brightness(1.12);
  transform: translateY(-1px);
}
.hHd-Xa_newSession::before {
  content: "";
  width: 26px;
  height: 26px;
  flex: 0 0 26px;
  background: url("data:image/png;base64,") center / contain no-repeat;
  image-rendering: pixelated;
}
.hHd-Xa_newSession svg { display: none; }

.qDHVXG_sectionLabel {
  color: #e0bb78;
  font-family: "Fusion Pixel Isaac", system-ui, sans-serif;
  font-size: 15px;
  letter-spacing: .06em;
  text-shadow: 0 2px #120906;
  border-bottom: 1px solid rgba(174, 104, 61, .38);
  box-shadow: 0 5px 8px -8px #000;
}

.qDHVXG_searchInput {
  color: var(--isaac-ink);
  background: rgba(17, 16, 16, .88);
  border: 1px solid #49413d;
  border-radius: 6px;
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, .4);
}
.qDHVXG_searchInput:focus { border-color: #8c624d; }
.qDHVXG_searchInput::placeholder { color: #807973; }

.YDXeBa_sessionRow {
  color: #d4d0ca;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 6px;
}
.YDXeBa_sessionRow:hover {
  color: #f0ede8;
  background: rgba(83, 72, 66, .34);
  border-color: rgba(130, 95, 75, .3);
}
.YDXeBa_sessionRow.YDXeBa_selected {
  color: #f7f2eb;
  background:
    radial-gradient(circle at 7% 55%, rgba(178, 56, 39, .34), transparent 18%),
    linear-gradient(90deg, rgba(107, 40, 30, .72), rgba(45, 31, 27, .64));
  border-color: rgba(156, 72, 54, .68);
  box-shadow: inset 4px 0 #d4543f, inset 0 0 22px rgba(113, 25, 18, .34), 0 3px 8px rgba(0, 0, 0, .24);
}
.YDXeBa_projectRow {
  color: #ddc9b2;
  font-family: "Fusion Pixel Isaac", system-ui, sans-serif;
  letter-spacing: .025em;
  text-shadow: 0 1px #000;
}
.YDXeBa_folder {
  width: 22px;
  height: 22px;
  flex: 0 0 22px;
  background: url("data:image/png;base64,") center / 22px 22px no-repeat;
  image-rendering: pixelated;
  filter: saturate(.82) drop-shadow(0 2px 1px rgba(0, 0, 0, .72));
}
.YDXeBa_folder > svg { visibility: hidden; }
.YDXeBa_folderActive {
  filter: saturate(1.12) brightness(1.18) drop-shadow(0 0 4px rgba(215, 133, 76, .42));
}
.hHd-Xa_footArea {
  background: rgba(13, 13, 14, .72);
  border-top: 1px solid rgba(123, 76, 52, .27);
}
.Nqubda_badge[data-cordis-badge] {
  position: relative;
  color: #ead9c3;
}
.Nqubda_badge[data-cordis-badge]::before {
  content: "";
  position: absolute;
  left: 5px;
  top: 50%;
  width: 22px;
  height: 22px;
  transform: translateY(-50%);
  background: url("data:image/png;base64,") center / contain no-repeat;
  image-rendering: pixelated;
  pointer-events: none;
}
.Nqubda_badge[data-cordis-badge] > svg { visibility: hidden; }

/* ---------------- Session frame: a dungeon lintel, not generic app chrome ---------------- */
.wSkVaW_header {
  color: var(--isaac-ink);
  background-color: #141315;
  background-image:
    linear-gradient(180deg, rgba(15, 11, 10, .72), rgba(13, 12, 13, .94)),
    url("data:image/png;base64,");
  background-repeat: no-repeat;
  background-position: center top;
  background-size: 100% 100%, 100% 64px;
  border-bottom: 1px solid rgba(130, 77, 51, .42);
  box-shadow: 0 1px 8px rgba(0, 0, 0, .28);
}
.wSkVaW_header::after {
  content: "";
  position: absolute;
  z-index: 2;
  left: 0;
  right: 0;
  bottom: -4px;
  height: 7px;
  pointer-events: none;
  background:
    radial-gradient(circle at 18% 0, #7e2119 0 3px, transparent 3.5px),
    radial-gradient(circle at 52% 0, #9b2a1e 0 2px, transparent 2.5px),
    radial-gradient(circle at 76% 0, #6d1b15 0 4px, transparent 4.5px);
  opacity: .72;
}
.wSkVaW_crumb,
.wSkVaW_crumbCurrent {
  color: #eee5da;
  font-family: "Fusion Pixel Isaac", system-ui, sans-serif;
  letter-spacing: .025em;
  text-shadow: 0 2px 3px #000;
}
.wSkVaW_tab {
  color: #99938d;
  font-family: "Fusion Pixel Isaac", system-ui, sans-serif;
  letter-spacing: .04em;
}
.wSkVaW_tab:hover { color: #e0dcd7; }
.wSkVaW_tab.wSkVaW_tabActive {
  color: #d9ae6a;
  border-bottom-color: var(--isaac-blood-bright);
}
.nL4_yW_sessionLogButton {
  position: relative;
  color: #cbc6c0;
  background: rgba(29, 27, 27, .72);
  border-color: rgba(104, 84, 73, .55);
}
.nL4_yW_sessionLogButton::after {
  content: "";
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  background: url("data:image/png;base64,") center / contain no-repeat;
  image-rendering: pixelated;
}
.nL4_yW_sessionLogButton svg { display: none; }

/* ---------------- Conversation: one complete basement room ----------------
 * The wall texture is the page-wide ground plane. Earlier versions only
 * painted two 25px strips around the transcript, leaving a black void. */
.wSkVaW_scrollBody[data-conversation-scroll],
.Md3f7G_scroll {
  color: var(--isaac-ink);
}
.wSkVaW_scrollBody[data-conversation-scroll] {
  background-color: #130a07;
  background-image:
    linear-gradient(rgba(18, 10, 8, .3), rgba(18, 10, 8, .48)),
    var(--isaac-burning-room-image);
  background-repeat: no-repeat, no-repeat;
  background-position: center, center;
  background-size: cover, cover;
  background-attachment: scroll;
}
.Md3f7G_scroll {
  background: transparent;
}
.wSkVaW_composerSeat {
  /* Keep the shared room visible beside the centered composer. A full-width
   * seat gradient read as a brown sheet on both the hero and conversation. */
  background: transparent !important;
}
.Md3f7G_column {
  position: relative;
  color: var(--isaac-ink);
  filter: drop-shadow(-18px 0 18px rgba(0, 0, 0, .18)) drop-shadow(18px 0 18px rgba(0, 0, 0, .18));
}

.Md3f7G_flowItem { position: relative; }
.Md3f7G_flowItem[data-chat-flow-kind="user"]::before,
.Md3f7G_flowItem[data-chat-flow-kind="tool-call"]::before,
.Md3f7G_flowItem[data-chat-flow-kind="context"]::before,
.Md3f7G_flowItem[data-chat-flow-kind="assistant-step"]:not(:has(.QWLzlG_root, .o3BgMG_root, .CY-8Ka_root))::before {
  content: "";
  position: absolute;
  top: 3px;
  left: -39px;
  z-index: 2;
  width: 29px;
  height: 29px;
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
  image-rendering: pixelated;
  filter: drop-shadow(0 3px 2px rgba(0, 0, 0, .85));
}
.Md3f7G_flowItem[data-chat-flow-kind="user"]::before {
  left: auto;
  right: -39px;
  top: 9px;
  background-image: url("data:image/png;base64,");
}
.Md3f7G_flowItem[data-chat-flow-kind="tool-call"]::before { background-image: url("data:image/png;base64,"); }
.Md3f7G_flowItem[data-chat-flow-kind="context"]::before { background-image: url("data:image/png;base64,"); }
.Md3f7G_flowItem[data-chat-flow-kind="assistant-step"]:not(:has(.QWLzlG_root, .o3BgMG_root, .CY-8Ka_root))::before {
  background-image: url("data:image/png;base64,");
}

/* Keep assistant prose open; cards are reserved for semantic blocks. */
.Sxvs8a_root {
  color: var(--isaac-ink);
  background: transparent;
  border: 0;
  border-radius: 0;
}
.Sxvs8a_root a { color: #cfa665; }
.Sxvs8a_root hr { border-color: rgba(128, 117, 108, .28); }

.gdEzaW_bubble {
  color: #eeeae5;
  background:
    repeating-linear-gradient(0deg, rgba(71, 36, 25, .14) 0 2px, transparent 2px 6px),
    linear-gradient(145deg, #432c27, #2b211f);
  border: 2px solid #1b0e0b;
  outline: 1px solid #734a3b;
  outline-offset: -4px;
  border-radius: 5px 11px 3px 9px;
  box-shadow: inset 0 1px rgba(255, 238, 220, .06), 5px 7px 0 rgba(0, 0, 0, .14), 0 4px 18px rgba(0, 0, 0, .25);
}

/* Semantic traces use accents, not a stack of brown boxes. */
.QWLzlG_root[data-variant="think"] {
  color: #aaa4a0;
  background: linear-gradient(90deg, rgba(105, 45, 35, .12), transparent 72%);
  border: 0;
  border-left: 3px solid rgba(177, 61, 44, .78);
  border-bottom: 1px dashed rgba(112, 66, 54, .28);
  border-radius: 2px;
}
.QWLzlG_root[data-variant="think"] .QWLzlG_row { color: #aaa4a0; }
.QWLzlG_root[data-variant="think"] .QWLzlG_leading { color: #b9503f; }
.QWLzlG_root[data-variant="think"] .QWLzlG_leading > span:first-child {
  width: 18px;
  height: 18px;
  background: url("data:image/png;base64,") center / contain no-repeat;
  image-rendering: pixelated;
  filter: drop-shadow(0 2px 1px #000);
}
.QWLzlG_root[data-variant="think"] .QWLzlG_leading > span:first-child svg { visibility: hidden; }

.o3BgMG_root,
.iWrAna_row {
  color: #c5c0ba;
  background:
    linear-gradient(90deg, rgba(96, 50, 35, .16), transparent 52%),
    #101012;
  border: 2px solid #09090a;
  outline: 1px solid rgba(106, 75, 60, .44);
  outline-offset: -3px;
  border-radius: 4px;
  box-shadow: 0 3px 0 rgba(0, 0, 0, .2);
}
.o3BgMG_title { color: #cba161; }
.o3BgMG_summary { color: #aaa49e; }
.o3BgMG_ioCard {
  color: #d1cdc7;
  background: #0c0d0f;
  border: 1px solid #353438;
  border-radius: 4px;
}
.o3BgMG_ioLabel { color: #b95a49; }
.o3BgMG_ioText {
  color: #cbc7c1;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
}

.CY-8Ka_root[data-variant="bash"] {
  color: #b7d0b5;
  background: #0d100e;
  border: 3px solid #070907;
  outline: 1px solid #465c49;
  outline-offset: -4px;
  border-left-color: #668168;
  border-radius: 3px;
}
.CY-8Ka_root[data-variant="bash"] .CY-8Ka_title { color: #a9d49e; }
.CY-8Ka_root[data-variant="bash"] .CY-8Ka_summary { color: #91ad8b; }
.CY-8Ka_root { color: #c5c0ba; }

.iWrAna_row,
.pC0e7a_root,
.FJxK0a_root { color: #bdb7b1; }

.pC0e7a_root {
  padding-left: 25px;
  background:
    url("data:image/png;base64,") 4px center / 19px 19px no-repeat,
    linear-gradient(90deg, rgba(52, 84, 112, .18), transparent 62%);
  border-left: 2px solid rgba(82, 128, 164, .54);
  image-rendering: pixelated;
}

.Md3f7G_column pre,
.Sxvs8a_root pre {
  color: #d3d9d1;
  background: #0b0c0e;
  border: 1px solid #343438;
  border-left: 3px solid #5b514b;
  border-radius: 6px;
  box-shadow: inset 0 1px 8px rgba(0, 0, 0, .48);
}
.Md3f7G_column :not(pre) > code,
.Sxvs8a_root :not(pre) > code {
  color: #e3d8c9;
  background: rgba(67, 58, 54, .62);
  border: 1px solid rgba(112, 95, 84, .42);
  border-radius: 4px;
}

/* ---------------- Composer: a usable treasure-room workbench ---------------- */
.uV2eYG_card[data-composer-card="true"] {
  color: var(--isaac-ink);
  background-color: #3f291f;
  background-image:
    radial-gradient(circle 3px at 11px 10px, #160d09 0 2px, #9a7258 2.5px 3px, transparent 3.5px),
    radial-gradient(circle 3px at calc(100% - 11px) 10px, #160d09 0 2px, #9a7258 2.5px 3px, transparent 3.5px),
    radial-gradient(circle 3px at 11px calc(100% - 10px), #160d09 0 2px, #9a7258 2.5px 3px, transparent 3.5px),
    radial-gradient(circle 3px at calc(100% - 11px) calc(100% - 10px), #160d09 0 2px, #9a7258 2.5px 3px, transparent 3.5px),
    repeating-linear-gradient(0deg, rgba(38, 18, 11, .22) 0 2px, transparent 2px 6px),
    linear-gradient(180deg, #533628, #35231c 62%, #281a15);
  border: 3px solid #130a07;
  outline: 1px solid #805039;
  outline-offset: -4px;
  border-radius: 7px;
  box-shadow: inset 0 2px rgba(255, 220, 181, .1), inset 0 -4px rgba(0, 0, 0, .3), 0 10px 28px rgba(0, 0, 0, .48);
}
.uV2eYG_primary {
  color: #f1d7a8;
  background:
    radial-gradient(circle at 50% 42%, #8f5f3e, #3d251c 68%),
    #3d251c;
  border: 3px solid #160b08;
  outline: 1px solid #9c6c48;
  outline-offset: -4px;
  box-shadow: 0 4px 0 #160b08, inset 0 2px rgba(255, 230, 190, .12);
}
.uV2eYG_primary:hover:not(:disabled) {
  filter: brightness(1.18);
  transform: translateY(-1px);
}
.uV2eYG_input,
.uV2eYG_mirror,
.uV2eYG_backdrop {
  color: #ece8e3;
  caret-color: #cf9e59;
}
.uV2eYG_input::placeholder { color: #b69b88; }
.uV2eYG_tools,
.uV2eYG_add,
.Sh0Q9G_trigger,
._7KE1Ra_trigger { color: #c4b7a8; }

.FJxK0a_root {
  color: #9f9287;
  background: rgba(10, 8, 8, .78);
  border-top: 1px solid rgba(139, 83, 52, .32);
  font-family: "Fusion Pixel Isaac", ui-monospace, monospace;
  letter-spacing: .01em;
}

/* ---------------- Details drawer ---------------- */
.ydkMvW_root {
  color: #dedad4;
  background:
    linear-gradient(rgba(18, 15, 15, .9), rgba(18, 15, 15, .94)),
    url("data:image/png;base64,") top center / 100% auto repeat-y;
  border-left: 4px solid #20110d;
  box-shadow: -8px 0 24px rgba(0, 0, 0, .28);
}
.ydkMvW_header {
  background:
    linear-gradient(rgba(22, 15, 13, .72), rgba(22, 15, 13, .88)),
    url("data:image/png;base64,") center / cover;
  border-bottom: 2px solid #4d2c20;
}
.ydkMvW_title {
  color: #cba060;
}
.ydkMvW_body { background: #171619; }
.ydkMvW_empty { color: #817b76; }

/* ---------------- New session: recognizable burning-basement room ---------------- */
.wSkVaW_root[data-phase="hero"] .wSkVaW_scrollBody {
  color: #eeeae5;
  background: transparent;
}
.pXSMma_root,
.pXSMma_headline {
  color: #f0ece7;
  font-family: "Fusion Pixel Isaac", system-ui, sans-serif;
  letter-spacing: .035em;
