/* ========================================================================== */
/* v8 — Isaac object grammar                                                   */
/*                                                                            */
/* Isaac does not use one universal "dark card".  Notes are torn paper,       */
/* actions happen at doors/pedestals, system traces are room fixtures, and     */
/* danger is communicated with blood.  These overrides deliberately give      */
/* each work-surface family a different physical identity.                     */
/* ========================================================================== */

/* Replace the CSS approximations on the empty-room stage with actual sprites. */
.isaacDoor {
  top: -7px;
  width: 192px;
  height: 96px;
  border: 0;
  border-radius: 0;
  background: url("data:image/png;base64,") center top / 192px 96px no-repeat;
  box-shadow: none;
  image-rendering: pixelated;
  filter: drop-shadow(0 12px 9px rgba(0, 0, 0, .72));
}
.isaacDoor::after { display: none; }
/* Sidebar: start a run from a torn save-sheet, not a rounded wood button. */
.hHd-Xa_newSession {
  color: #34251f;
  text-shadow: 0 1px rgba(255, 255, 255, .22);
  background: url("data:image/png;base64,") center / 100% 100% no-repeat;
  border: 0;
  outline: 0;
  border-radius: 0;
  box-shadow: 0 5px 7px rgba(0, 0, 0, .42);
  transform: rotate(-.12deg);
}
.hHd-Xa_newSession:hover {
  color: #211714;
  filter: brightness(1.06) saturate(.92);
  transform: translateY(-1px) rotate(.18deg);
}
.qDHVXG_searchInput {
  background:
    radial-gradient(ellipse at 50% 130%, rgba(91, 48, 35, .34), transparent 58%),
    #0d0b0c;
  border: 0;
  border-radius: 0;
  clip-path: polygon(5px 0, calc(100% - 9px) 0, 100% 5px, calc(100% - 3px) 100%, 7px 100%, 0 calc(100% - 6px));
  box-shadow: inset 0 0 0 2px #41342e, inset 0 0 12px #000;
}
.YDXeBa_sessionRow {
  border-radius: 0;
  clip-path: polygon(4px 0, calc(100% - 3px) 0, 100% 5px, calc(100% - 4px) 100%, 0 100%);
}
.YDXeBa_sessionRow.YDXeBa_selected {
  border-color: transparent;
  background:
    radial-gradient(ellipse at 9% 50%, rgba(193, 58, 39, .62), transparent 24%),
    linear-gradient(90deg, rgba(127, 37, 26, .82), rgba(70, 29, 24, .62) 58%, transparent 100%);
  box-shadow: inset 5px 0 #e05d45, inset 0 -2px rgba(62, 13, 10, .62);
}

/* Session log is a small paper tag pinned to the dungeon lintel. */
.nL4_yW_sessionLogButton {
  color: #392b24;
  background: url("data:image/png;base64,") center / 100% 100% no-repeat;
  border: 0;
  border-radius: 0;
  box-shadow: 0 3px 7px rgba(0, 0, 0, .4);
  transform: rotate(.3deg);
}

/* User prompt = Dad's note.  It is intentionally the only large pale surface. */
.gdEzaW_bubble {
  color: #33251f;
  padding: 22px 34px;
  background: url("data:image/png;base64,") center / 100% 100% no-repeat;
  border: 0;
  border-image: none;
  border-radius: 0;
  outline: 0;
  box-shadow: 5px 8px 11px rgba(0, 0, 0, .28);
  text-shadow: 0 1px rgba(255, 255, 255, .16);
  transform: rotate(.08deg);
}
.gdEzaW_bubble a,
.gdEzaW_bubble code { color: #5e201a; }

/* Assistant prose remains open, like HUD text over a room. */
