/* ========================================================================== */
/* v9 — composition polish                                                    */
/*                                                                            */
/* Keep v8's object grammar, but make the room read as one authored scene:    */
/* complete door silhouettes, symmetric practical lighting, integer-ish      */
/* sprite scales, quieter fixtures and a clearer information hierarchy.       */
/* ========================================================================== */

/* Room composition: show complete entrances instead of floating lintels. */
.isaacStage {
  filter: saturate(.94) contrast(1.09) brightness(.94);
}
.isaacStage::before {
  background:
    radial-gradient(ellipse at calc(50% + 140px) 48%, transparent 0 29%, rgba(0, 0, 0, .2) 67%, rgba(0, 0, 0, .53) 100%),
    linear-gradient(90deg, rgba(0, 0, 0, .48), transparent 24%, transparent 78%, rgba(0, 0, 0, .43)),
    linear-gradient(180deg, rgba(0, 0, 0, .22), transparent 24%, transparent 70%, rgba(0, 0, 0, .5));
}
.isaacStage::after {
  background:
    radial-gradient(circle at calc(50% - 380px) 49%, rgba(255, 105, 34, .34), transparent 9%),
    radial-gradient(circle at calc(50% + 660px) 49%, rgba(255, 105, 34, .31), transparent 9%);
  opacity: .48;
}
.isaacTorch {
  top: 46.5%;
  width: 18px;
  height: 36px;
  opacity: .2;
  filter: drop-shadow(0 0 18px rgba(244, 91, 28, .9));
}
.isaacTorchLeft {
  left: calc(50% + 140px - min(34vw, 520px));
}
.isaacTorchRight {
  right: auto;
  left: calc(50% + 140px + min(34vw, 520px));
}
body[data-dsh-isaac]:has(.wSkVaW_root[data-phase="hero"]) .isaacTorch {
  opacity: .82;
}
.isaacDoor {
  top: -8px;
  width: 176px;
  height: 88px;
  background: url("data:image/png;base64,") center top / 176px 88px no-repeat;
  filter: drop-shadow(0 13px 10px rgba(0, 0, 0, .72));
}
body[data-dsh-isaac]:has(.wSkVaW_root[data-phase="hero"]) .isaacDoor { opacity: .82; }

/* Hero: stronger title hierarchy without adding another generic container. */
.wSkVaW_composerHero {
  isolation: isolate;
}
.wSkVaW_composerHero .pXSMma_headline {
  position: relative;
  min-height: 38px;
  align-items: center;
  color: #f2e6d2;
  text-shadow: 0 3px 2px #160b08, 0 0 14px rgba(0, 0, 0, .95);
}
.wSkVaW_composerHero .pXSMma_headline::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 248px;
  height: 4px;
  transform: translateX(-50%);
  background: linear-gradient(90deg, transparent, #692119 12% 88%, transparent);
  clip-path: polygon(0 25%, 18% 0, 47% 32%, 76% 6%, 100% 40%, 83% 100%, 49% 68%, 13% 92%);
  opacity: .82;
}
.wSkVaW_composerHero .pXSMma_headlineText {
  font-size: 29px;
  letter-spacing: .075em;
}
.wSkVaW_composerHero .pXSMma_fish {
  color: #f0dfc6;
  filter: drop-shadow(0 3px 2px #140907);
}
.wSkVaW_composerHero .pXSMma_previewBadge {
  color: #e8d3b0;
  padding: 3px 9px;
  background: linear-gradient(#633126, #361b17);
  border: 0;
  border-radius: 0;
  box-shadow: inset 0 0 0 1px #8c5940, 0 3px 4px rgba(0, 0, 0, .42);
  clip-path: polygon(4px 0, 100% 2px, calc(100% - 3px) 100%, 0 calc(100% - 2px));
}
.wSkVaW_composerHero .wSkVaW_heroWorkspaceRow {
  margin-top: 7px;
}
.wSkVaW_composerHero .pXSMma_workspace {
  min-height: 31px;
  padding-left: 34px;
  padding-right: 12px;
  filter: sepia(.07) contrast(1.03);
}

/* Treasure-room composer: use the full golden doorway, not a crown-shaped
 * fragment. The posts descend into the dark editable room. */
.uV2eYG_card[data-composer-card="true"] {
  box-shadow:
    inset 0 0 0 3px #76503a,
    inset 0 0 0 7px #160d0b,
