/* ========================================================================== */
/* v10 — pickups are the interface                                            */
/*                                                                            */
/* A tiny original glyph over an Isaac pickup reads as two competing icons.   */
/* v10 removes that badge system, trims transparent sprite padding, and lets   */
/* recognizable pickups become structural parts of each content object.       */
/* ========================================================================== */

/* One readable pickup per icon button; no bottom-right mini glyphs. */
.hHd-Xa_toggle > svg,
.qDHVXG_searchButton > svg,
button[aria-label="视图选项"] > svg,
button[aria-label="添加工作区"] > svg,
.uV2eYG_add > svg {
  display: none !important;
}
.hHd-Xa_toggle::before,
.qDHVXG_searchButton::before,
button[aria-label="视图选项"]::before,
button[aria-label="添加工作区"]::before,
.uV2eYG_add::before {
  inset: -1px;
  background-size: contain;
  filter: drop-shadow(0 3px 2px rgba(0, 0, 0, .86));
}
.hHd-Xa_toggle:hover::before,
.qDHVXG_searchButton:hover::before,
button[aria-label="视图选项"]:hover::before,
button[aria-label="添加工作区"]:hover::before,
.uV2eYG_add:hover::before {
  transform: translateY(-2px) scale(1.08);
}

/* The Peeper is tall and was touching the clipped edge of the workspace
 * header. Keep the button hit target unchanged while fitting the sprite. */
.qDHVXG_searchButton::before {
  inset: 4px;
}
.qDHVXG_searchButton:hover::before {
  transform: translateY(-1px) scale(1.05);
}

/* Larger lane pickups establish message identity before the frame is read. */
.Md3f7G_flowItem[data-chat-flow-kind="user"]::before,
.Md3f7G_flowItem[data-chat-flow-kind="tool-call"]::before,
.Md3f7G_flowItem[data-chat-flow-kind="context"]::before,
.Md3f7G_flowItem[data-chat-flow-kind="assistant-step"]:not(:has(.QWLzlG_root, .o3BgMG_root, .CY-8Ka_root))::before {
  left: -45px;
  width: 34px;
  height: 34px;
}
.Md3f7G_flowItem[data-chat-flow-kind="user"]::before {
  display: none;
}
.Md3f7G_flowItem[data-chat-flow-kind="tool-call"]::before,
.Md3f7G_flowItem[data-chat-flow-kind="context"]::before,
.Md3f7G_flowItem[data-chat-flow-kind="assistant-step"]:has(.iWrAna_row)::before {
  display: none;
}

/* Long conversations place the composer over the bottom of the message rail.
 * Anything hung outside a flow item therefore collides with the composer.
 * Keep Isaac objects inside their own rows instead of on that rail. */
.Md3f7G_flowItem::before {
  display: none !important;
}

/* Dad's Note pins the actual user paper. */
.gdEzaW_bubble {
  position: relative;
}
.gdEzaW_bubble::before {
  content: "";
  position: absolute;
  z-index: 4;
  top: -12px;
  right: 20px;
  width: 34px;
  height: 34px;
  background: url("data:image/png;base64,") center / contain no-repeat;
  image-rendering: pixelated;
  filter: drop-shadow(0 3px 2px rgba(0, 0, 0, .68));
  transform: rotate(5deg);
  pointer-events: none;
}

/* Cain's Eye is the thinking marker, not a generic sparkle glyph. */
.QWLzlG_root[data-variant="think"] {
  min-height: 30px;
}
.QWLzlG_root[data-variant="think"] .QWLzlG_row,
.QWLzlG_root[data-variant="think"] .QWLzlG_leading {
  min-height: 30px;
  align-items: center;
}
.QWLzlG_root[data-variant="think"] .QWLzlG_leading {
  width: 26px;
  min-width: 26px;
  flex: 0 0 26px;
  margin-right: 6px;
  justify-content: center;
  overflow: visible;
}
.QWLzlG_root[data-variant="think"] .QWLzlG_leading > span:first-child {
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  margin: 0;
  background-size: contain;
  filter: drop-shadow(0 3px 2px #000);
}

/* A generic tool is an item-room pickup: Bag of Crafting on an altar, held
 * by real basement stones. */
.o3BgMG_root {
  min-height: 44px;
  padding-left: 0;
}
.o3BgMG_root .o3BgMG_row {
  min-height: 44px;
  padding-left: 50px;
  align-items: center;
}
.o3BgMG_root::before {
  content: "";
  position: absolute;
  z-index: 4;
  left: 6px;
  top: 2px;
  width: 38px;
  height: 40px;
  transform: none;
  background-image: url("data:image/png;base64,"), url("data:image/png;base64,");
  background-position: center 0, center bottom;
  background-repeat: no-repeat;
  background-size: 28px 30px, 38px 26px;
  image-rendering: pixelated;
  filter: drop-shadow(0 4px 2px rgba(0, 0, 0, .76));
  pointer-events: none;
}

/* Read gets an unmistakable blue Book of Virtues. Book of Secrets looked
 * exactly like a browser's missing-image placeholder at UI scale. */
.o3BgMG_root[data-tool="read"]::before {
  background-image: url("data:image/png;base64,");
  background-position: center;
  background-size: 31px 37px;
}

/* Skill loading is a ladder/progression cue. File reads above keep the
 * Book of Secrets on an altar, so the question-mark cover cannot be mistaken
 * for a duplicated browser placeholder. */
.iWrAna_row {
  min-height: 42px;
  padding-left: 40px;
}
.iWrAna_row::before {
  content: "";
  position: absolute;
  z-index: 3;
  left: 9px;
  top: 50%;
  width: 28px;
  height: 32px;
  transform: translateY(-50%);
  background: url("data:image/png;base64,") center / contain no-repeat;
  image-rendering: pixelated;
  filter: drop-shadow(0 3px 2px rgba(0, 0, 0, .78));
  pointer-events: none;
}

/* The map scrap carries a full-size Blue Map pickup. */
.pC0e7a_root {
  min-height: 42px;
  padding-left: 48px;
}
.pC0e7a_root::before {
  left: 10px;
  width: 31px;
  height: 32px;
  filter: drop-shadow(0 3px 2px rgba(0, 0, 0, .55));
}

/* Crawlspace calls deserve a readable trapdoor silhouette. */
.CY-8Ka_root[data-variant="bash"] {
  min-height: 54px;
  padding-left: 58px;
}
.CY-8Ka_root[data-variant="bash"]::before {
  left: 5px;
  width: 48px;
  height: 48px;
}

/* ========================================================================== */
/* v11 — one native pickup-banner language                                    */
/*                                                                            */
/* Tool rows are short status notices, not separate rooms. The game already   */
/* has a purpose-built visual for this: Effect_024_Streak, used behind pickup  */
/* names and subtitles. Bash, ordinary tools, reads, skills, and context now   */
/* share that native banner; the small pickup alone identifies the subtype.    */
/* ========================================================================== */

.o3BgMG_root,
.iWrAna_row,
.CY-8Ka_root[data-variant="bash"],
.pC0e7a_root {
  position: relative;
  min-height: 48px;
  color: #f1ece5;
  background: url("data:image/png;base64,") center / 100% 100% no-repeat;
  border: 0;
  border-radius: 0;
  outline: 0;
  clip-path: none;
  box-shadow: none;
  text-shadow: 0 2px 1px #000, 0 0 4px rgba(0, 0, 0, .9);
  image-rendering: pixelated;
}

.o3BgMG_root:hover,
.iWrAna_row:hover,
.CY-8Ka_root[data-variant="bash"]:hover,
.pC0e7a_root:hover {
  filter: brightness(1.08);
}

/* Remove the invented rocks, altar, cyan crawlspace frame, and paper scrap. */
.o3BgMG_root::after { content: none; display: none; }
.o3BgMG_root {
  min-height: 48px;
  padding-left: 0;
}
.o3BgMG_root .o3BgMG_row {
  min-height: 48px;
  padding-left: 48px;
  padding-right: 18px;
  align-items: center;
}
.o3BgMG_root::before {
  left: 10px;
  top: 50%;
  width: 30px;
  height: 32px;
  transform: translateY(-50%);
  background-image: url("data:image/png;base64,");
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
  filter: drop-shadow(0 3px 2px #000);
}
.o3BgMG_root[data-tool="read"]::before {
  width: 29px;
  height: 34px;
  background-image: url("data:image/png;base64,");
  background-position: center;
  background-size: contain;
}
.o3BgMG_root .o3BgMG_leading > span:first-child {
  display: none;
}
.o3BgMG_title,
.CY-8Ka_root[data-variant="bash"] .CY-8Ka_title {
  color: #fffaf2;
  font-family: "Fusion Pixel Isaac", system-ui, sans-serif;
  font-weight: 700;
}
.o3BgMG_summary,
.CY-8Ka_root[data-variant="bash"] .CY-8Ka_summary {
  color: #d4cbc1;
}

.CY-8Ka_root[data-variant="bash"] {
  min-height: 48px;
  padding-left: 48px;
  padding-right: 18px;
  color: #f1ece5;
}
.CY-8Ka_root[data-variant="bash"]::before {
  left: 10px;
  top: 50%;
  width: 30px;
  height: 30px;
  transform: translateY(-50%);
  background: url("data:image/png;base64,") center / contain no-repeat;
  filter: drop-shadow(0 3px 2px #000);
}
.CY-8Ka_root[data-variant="bash"] .CY-8Ka_leading svg {
  visibility: hidden;
}

.iWrAna_row {
  min-height: 46px;
  padding-left: 46px;
  padding-right: 18px;
}
.iWrAna_row::before {
  left: 10px;
  width: 28px;
  height: 30px;
}

.pC0e7a_root {
  min-height: 46px;
  padding: 10px 18px 10px 46px;
  color: #eee8e0;
}
.pC0e7a_root::before {
  left: 10px;
  width: 28px;
  height: 30px;
  filter: drop-shadow(0 3px 2px #000);
}
.pC0e7a_root [class*="_title_"],
.pC0e7a_root .pC0e7a_source,
.pC0e7a_root .pC0e7a_sep {
  color: #f5eee5;
  text-shadow: 0 2px 1px #000;
}

/* A sent prompt must remain a reading surface. The stock 525px cap made long
 * prompts taller than the viewport, placing their beginning behind the header
 * and their ending behind the composer. Keep Dad's Note, but use the rail. */
.gdEzaW_userStack {
  width: 100%;
  max-width: 100%;
}
.gdEzaW_bubble {
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  padding: 18px 22px;
  color: #211713;
  font-size: 16px;
  line-height: 1.5;
  overflow-wrap: anywhere;
  background-color: #dcc9bd;
  text-shadow: none;
}
.gdEzaW_bubble [class*="_text_"] {
  color: #211713 !important;
}
.gdEzaW_bubble a,
.gdEzaW_bubble code {
  color: #681f18;
}
.gdEzaW_userRow {
  scroll-margin-top: 96px;
  scroll-margin-bottom: 180px;
}
.gdEzaW_bubble::before {
  top: -13px;
  right: 16px;
  width: 30px;
  height: 30px;
}

/* ========================================================================== */
/* v12 — code blocks are Isaac notes, not stock black developer panels        */
/*                                                                            */
/* The stock component paints three independent dark layers (block, sticky    */
/* banner, and pre). Flatten all three onto the game's paper note so the       */
/* language label, copy action, plain code, and Shiki code read as one object. */
/* ========================================================================== */

body[data-dsh-isaac] :is(.Md3f7G_column, .Sxvs8a_root) .md-code-block {
  --shiki-background: transparent;
  --shiki-foreground: #2d211b;
  --shiki-token-comment: #6b7280;
