body[data-dsh-isaac] .o3BgMG_diffBody [class*="_body_"] {
  box-sizing: border-box;
  width: auto;
  margin-inline: 18px;
}

body[data-dsh-isaac] .o3BgMG_ioSection {
  padding-inline: 22px;
}

body[data-dsh-isaac] .o3BgMG_ioDivider {
  margin-inline: 18px;
}

@media (max-width: 720px) {
  body[data-dsh-isaac] :is(
    .gdEzaW_bubble,
    .Sxvs8a_root blockquote,
    .Md3f7G_column .md-code-block,
    .Sxvs8a_root .md-code-block,
    .o3BgMG_diffBody,
    .o3BgMG_readBody,
    .o3BgMG_ioCard
  ) {
    background-size: 100% 100%, calc(100% - 22px) calc(100% - 20px);
  }

  body[data-dsh-isaac] .gdEzaW_bubble {
    padding-inline: 24px;
  }
}

/* ========================================================================== */
/* v16 — remaining Cordis/context paper wells                                 */
/*                                                                            */
/* Cordis result cards and expanded context payloads use their own components */
/* instead of the generic code/tool-detail classes covered above.  Give both  */
/* the same opaque reading centre while preserving the torn paper silhouette. */
/* ========================================================================== */

body[data-dsh-isaac] .cvtE3a_output,
body[data-dsh-isaac] .pC0e7a_body {
  box-sizing: border-box;
  color: #2d211c;
  background-color: transparent;
  background-image:
    url("data:image/png;base64,"),
    linear-gradient(180deg, #eadde1 0%, #e7d7dc 100%);
  background-position: center, center;
  background-size: 100% 100%, calc(100% - 28px) calc(100% - 24px);
  background-repeat: no-repeat, no-repeat;
  border: 0;
  border-radius: 0;
  outline: 0;
  clip-path: none;
  box-shadow: 3px 5px 8px rgba(0, 0, 0, .22);
  text-shadow: none;
}

/* Standalone Cordis output is still a scrollable/preformatted result, but its
 * copy now stays clear of the transparent torn edge. */
body[data-dsh-isaac] .cvtE3a_output {
  min-height: 52px;
  padding: 17px 30px;
  color: #2d211c;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

/* The expanded context payload contains a pre plus optional definition-list
 * metadata.  Remove their inherited terminal slab so the paper reads as one
 * continuous surface. */
body[data-dsh-isaac] .pC0e7a_body {
  padding: 18px 30px 20px;
}

body[data-dsh-isaac] .pC0e7a_body .NM4-hq_text {
  margin: 0;
  padding: 0;
  color: #2d211c;
  background: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  clip-path: none;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

body[data-dsh-isaac] .pC0e7a_body :is(
  .NM4-hq_fields,
  .NM4-hq_field,
  .NM4-hq_fieldKey,
  .NM4-hq_fieldValue
) {
  color: #4b382e;
  text-shadow: none;
}

@media (max-width: 720px) {
  body[data-dsh-isaac] .cvtE3a_output,
  body[data-dsh-isaac] .pC0e7a_body {
    background-size: 100% 100%, calc(100% - 22px) calc(100% - 20px);
  }

  body[data-dsh-isaac] .cvtE3a_output,
  body[data-dsh-isaac] .pC0e7a_body {
    padding-inline: 24px;
  }
}

/* ========================================================================== */
/* v17 — light-mode/readability fixes from user feedback                      */
/* ========================================================================== */

/* The sidebar logo row should blend into the basement material instead of
 * floating as a separate light/dark panel. */
body[data-dsh-isaac]:not([data-ds-dark-theme]) .hHd-Xa_logoRow {
  background: transparent;
  border-bottom-color: rgba(122, 76, 52, .22);
}

/* Generic menus (including the lower-left settings popover) must never stay a
 * stock white box with unreadable ink. Theme them like the other dungeon
 * pickers; existing specific menus keep their more specific rules. */
body[data-dsh-isaac] div[role="menu"] {
  color: #e9ded1;
  background:
    linear-gradient(rgba(25, 15, 13, .94), rgba(13, 10, 10, .98)),
    url("data:image/png;base64,") center / 360px auto;
  border: 0;
  border-radius: 0;
  box-shadow: inset 0 0 0 3px #684735, inset 0 0 0 7px #110a09, 0 15px 30px rgba(0, 0, 0, .62);
  clip-path: polygon(8px 0, calc(100% - 6px) 0, 100% 8px, calc(100% - 3px) 100%, 7px 100%, 0 calc(100% - 8px));
}

body[data-dsh-isaac] div[role="menu"] button[role="menuitem"] {
  min-width: 0;
  color: #e6d9ca;
  border-radius: 0;
}

body[data-dsh-isaac] div[role="menu"] button[role="menuitem"]:hover,
body[data-dsh-isaac] div[role="menu"] button[role="menuitem"][class*="_selected_"] {
  color: #fff0d6;
  background: linear-gradient(90deg, rgba(111, 53, 34, .72), rgba(66, 31, 24, .16));
  box-shadow: inset 4px 0 #c3813e;
}

/* Work-area prose in light mode: use dark readable ink instead of the light
 * HUD colors that were tuned for the dark room. */
body[data-dsh-isaac]:not([data-ds-dark-theme]) .Sxvs8a_root,
body[data-dsh-isaac]:not([data-ds-dark-theme]) .Sxvs8a_root p,
body[data-dsh-isaac]:not([data-ds-dark-theme]) .Sxvs8a_root li,
body[data-dsh-isaac]:not([data-ds-dark-theme]) .Sxvs8a_root div {
  color: #1f2937;
}

body[data-dsh-isaac]:not([data-ds-dark-theme]) .Sxvs8a_root h1,
body[data-dsh-isaac]:not([data-ds-dark-theme]) .Sxvs8a_root h2,
body[data-dsh-isaac]:not([data-ds-dark-theme]) .Sxvs8a_root h3 {
  color: #374151;
  text-shadow: none;
}

body[data-dsh-isaac]:not([data-ds-dark-theme]) .Sxvs8a_root a {
  color: #1d4ed8;
}

/* Comments and secondary code ink must stay readable on the light paper.
 * The token palette above already moved away from brown; this is a safety
 * net for any component that still emits its own comment color. */
body[data-dsh-isaac] :is(.Md3f7G_column, .Sxvs8a_root) .md-code-block,
body[data-dsh-isaac] :is(.o3BgMG_diffBody, .o3BgMG_readBody, .o3BgMG_ioCard) {
  --shiki-token-comment: #6b7280;
}

/* v17b — lower-left settings trigger/footer light-mode fixes */
body[data-dsh-isaac] .VOzbGW_trigger {
  color: #f0e8dc;
  background: radial-gradient(circle at 48% 42%, #55372a, #241713 72%);
  border: 1px solid #100806;
  outline: 1px solid rgba(139, 89, 62, .72);
  outline-offset: -2px;
  border-radius: 4px;
  box-shadow: inset 0 1px rgba(255, 229, 195, .1), 0 2px 4px rgba(0, 0, 0, .36);
}

body[data-dsh-isaac]:not([data-ds-dark-theme]) .hHd-Xa_footArea,
body[data-dsh-isaac]:not([data-ds-dark-theme]) .hHd-Xa_settingsArea,
body[data-dsh-isaac]:not([data-ds-dark-theme]) .hHd-Xa_footerActions {
  background: transparent !important;
}

manifest.dom:
(ctx) => {
  const body = document.body
  const stage = document.createElement('div')
  const leftTorch = document.createElement('i')
  const rightTorch = document.createElement('i')
  const door = document.createElement('i')

  stage.className = 'isaacStage'
  stage.dataset.isaacStage = ''
  stage.setAttribute('aria-hidden', 'true')
  leftTorch.className = 'isaacTorch isaacTorchLeft'
  rightTorch.className = 'isaacTorch isaacTorchRight'
  door.className = 'isaacDoor'
  stage.append(leftTorch, rightTorch, door)

  body.dataset.dshIsaac = ''
  body.prepend(stage)

  let semanticFrame = 0
  const classifyMode = (text) => {
    if (/PTC/i.test(text)) return 'ptc'
    if (/极简|Minimal/i.test(text)) return 'minimal'
    if (/创造|Creative/i.test(text)) return 'creative'
    if (/标准|Standard/i.test(text)) return 'standard'
    return 'generic'
  }
  const syncSemanticItems = () => {
    semanticFrame = 0
    document.querySelectorAll('.cubgiG_seat').forEach((button) => {
      button.dataset.isaacAgentMode = classifyMode(button.textContent || '')
    })
    document.querySelectorAll('.cubgiG_item').forEach((item) => {
      const button = item.closest('button')
      const name = item.querySelector('.cubgiG_itemName')
      if (button) button.dataset.isaacMode = classifyMode(name?.textContent || '')
    })
    document.querySelectorAll('button[role="menuitem"]').forEach((button) => {
      const text = (button.textContent || '').trim()
      if (text === 'Read Only') button.dataset.isaacAccess = 'read'
      else if (text === 'Workspace Write') button.dataset.isaacAccess = 'write'
      else if (text === 'Full access') button.dataset.isaacAccess = 'full'
    })
    document.querySelectorAll('.wSkVaW_scrollBody button').forEach((button) => {
      const text = (button.textContent || '').trim()
      if (text === '加载更早' || text === 'Load earlier') button.dataset.isaacLoadEarlier = ''
    })
  }
  const scheduleSemanticSync = () => {
    if (!semanticFrame) semanticFrame = requestAnimationFrame(syncSemanticItems)
  }
  const semanticObserver = new MutationObserver(scheduleSemanticSync)
  semanticObserver.observe(body, { childList: true, subtree: true, characterData: true })
  syncSemanticItems()

  ctx.effect(() => () => {
    semanticObserver.disconnect()
    if (semanticFrame) cancelAnimationFrame(semanticFrame)
    document.querySelectorAll('[data-isaac-agent-mode]').forEach((node) => delete node.dataset.isaacAgentMode)
    document.querySelectorAll('[data-isaac-mode]').forEach((node) => delete node.dataset.isaacMode)
    document.querySelectorAll('[data-isaac-access]').forEach((node) => delete node.dataset.isaacAccess)
    document.querySelectorAll('[data-isaac-load-earlier]').forEach((node) => delete node.dataset.isaacLoadEarlier)
    stage.remove()
    delete body.dataset.dshIsaac
  }, 'isaac-theme: ambient room stage')
}
